/** RikkaHub 预设主题，顺序与上游 PresetTheme.kt 的注册表一致。 */
val rikkahubPresets: List<Palette> = listOf(
    rikkahubSakuraPalette,
    rikkahubOceanPalette,
    rikkahubSpringPalette,
    rikkahubAutumnPalette,
    rikkahubBlackPalette,
    rikkahubMinimalPalette,
    rikkahubClaudePalette,
)

/**
 * 走「原样表面」通道的调色板：预设自带完整的中性阶梯
 * （surface、surfaceContainerLowest…surfaceContainerHighest、surfaceDim、
 * surfaceBright、surfaceVariant），
 * 直接采信它们，主题才铺满整个界面（`MemoTheme.authoredColorScheme` +
 * `AppSemanticColors.authored`）。Memo 自己那 9 套不走这条 ——
 * 它们的容器在生成时被压平到 surface，走原样会没有层次。
 *
 * 用户 2026-09-13：「语义 token（surfaceCard/surfaceFill）用得 226 处…
 * 我们要更 rikkhub 一样覆盖多，不然主题不好看」。
 */
val authoredSurfacePaletteIds: Set<String> = setOf(
    "sakura",
    "ocean",
    "spring",
    "autumn",
    "black",
    "minimal",
    "claude",
)

/**
 * 主题设置页列出的内置主题：Memo 默认主题 + RikkaHub 预设。
 * Memo 自己那 8 套（blue/green/purple/yellow/smokyRose/terracotta/monochrome/docTheme）
 * 不再出现在列表里，但 id 仍能解析（paletteById 兜底），老用户已选的主题不会失效。
 */
val themeChoices: List<Palette> = listOf(defaultPalette) + rikkahubPresets

/** id -> Palette：RikkaHub 预设优先，其次 Memo 生成的调色板，最后回落默认。 */
fun themePaletteById(id: String): Palette =
    rikkahubPresets.firstOrNull { it.id == id } ?: paletteById(id)
